INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM208PO3O', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{49x^2 - 121}{7x + 11}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$7x + 11$"},{"key":"B","text":"$7x - 11$"},{"key":"C","text":"$7x$"},{"key":"D","text":"$42x - 11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $49x^2 - 121$ is a difference of squares: $(7x)^2 - (11)^2 = (7x + 11)(7x - 11)$. Dividing by $(7x + 11)$ cancels the common factor, leaving $7x - 11$. The distractor $7x + 11$ results from a sign error, choosing the factor that was cancelled rather than the one that remains. The distractor $7x$ comes from partial reasoning, recognizing the square root of $49x^2$ but dropping the constant term. The distractor $42x - 11$ reflects a fundamental misunderstanding of how to factor a difference of squares.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21DJY7L', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ is defined by the equation $3x - y = 11$. Line $q$ is perpendicular to line $p$ and passes through the point $(6, 5)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting line $p$ in slope-intercept form gives $y = 3x - 11$, so the slope of line $p$ is $3$. A line perpendicular to $p$ has slope $-\\frac{1}{3}$. Using point-slope form with $(6, 5)$: $y - 5 = -\\frac{1}{3}(x - 6)$, which simplifies to $y = -\\frac{1}{3}x + 2 + 5 = -\\frac{1}{3}x + 7$. The $y$-intercept is $7$. The value $-7$ results from a sign error in the final calculation. The value $3$ comes from using the reciprocal slope $\\frac{1}{3}$ without negating it, giving $y - 5 = \\frac{1}{3}(x - 6) = \\frac{1}{3}x - 2$, so $y = \\frac{1}{3}x + 3$ and $y$-intercept $3$. The value $23$ arises from using the negative of the original slope ($-3$) rather than the negative reciprocal, giving $y - 5 = -3(x - 6) = -3x + 18$ and $y = -3x + 23$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21KLF7P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher wants to determine whether a new vitamin supplement causes improved memory in adults. The researcher gives the supplement to $60$ volunteers and measures their memory performance after $8$ weeks. No control group is used. Which of the following is a valid conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"The supplement causes improved memory because participants volunteered."},{"key":"B","text":"Any observed improvement in memory can be attributed to the supplement."},{"key":"C","text":"The study cannot establish that the supplement caused any observed improvement in memory."},{"key":"D","text":"The supplement has no effect on memory."}]$lyceon_json$::jsonb, 'C', NULL, E'Without a control group, there is no way to separate the effect of the supplement from other factors such as practice effects, placebo effect, or natural variation. Therefore, the study cannot establish a causal link. The claim that the supplement causes improvement because participants volunteered confuses voluntariness with causation and ignores the lack of a control group. The claim that any improvement can be attributed to the supplement incorrectly assumes causation without controlling for confounding variables. The claim that the supplement has no effect goes beyond what the study can determine — the study simply cannot distinguish an effect from confounds.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21PZ404', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $150$ voters in a city found that $57\\%$ plan to vote for Candidate A, with a margin of error of $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $57\\%$ of all voters in the city plan to vote for Candidate A."},{"key":"B","text":"Between $53\\%$ and $61\\%$ of the sampled voters plan to vote for Candidate A."},{"key":"C","text":"It is plausible that between $53\\%$ and $61\\%$ of all voters in the city plan to vote for Candidate A."},{"key":"D","text":"If another sample were taken, exactly $57\\%$ would again plan to vote for Candidate A."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $4$ percentage points means the plausible range for the population parameter is $57\\% \\pm 4\\%$, or between $53\\%$ and $61\\%$. This interval applies to the population, not just the sample. The claim that exactly $57\\%$ of all voters support Candidate A treats the sample statistic as the exact population value, ignoring sampling variability. The claim that the interval describes the sampled voters confuses the sample (which was directly observed) with the population inference. The claim that another sample would yield exactly $57\\%$ misunderstands that sample results vary from sample to sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22HBZ1M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same large population. Sample X consists of $250$ individuals and finds that $41\\%$ favor a proposal, with a margin of error of $\\pm 6.2$ percentage points. Sample Y consists of $1{,}000$ individuals and finds that $38\\%$ favor the proposal, with a margin of error of $\\pm 3.1$ percentage points. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The results are contradictory, so at least one sample must be biased."},{"key":"B","text":"The true population proportion is more likely to be $38\\%$ than $41\\%$ because Sample Y is larger."},{"key":"C","text":"The confidence intervals from both samples overlap, so the results are consistent with each other."},{"key":"D","text":"Since both margins of error are less than $7$ percentage points, the true proportion must be between $34\\%$ and $47\\%$."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample X''s confidence interval is $34.8\\%$ to $47.2\\%$, and Sample Y''s confidence interval is $34.9\\%$ to $41.1\\%$. These intervals overlap substantially (from about $34.9\\%$ to $41.1\\%$), so the two sample results are consistent with each other and could reflect the same population proportion. The claim that the results are contradictory misunderstands that different samples naturally yield different point estimates; overlap of the intervals shows no contradiction. The claim that the true proportion is more likely to be $38\\%$ conflates a larger sample with certainty about the point estimate — a larger sample narrows the interval but does not guarantee the point estimate is the parameter. The claim that the true proportion must be between $34\\%$ and $47\\%$ incorrectly merges the two intervals into a single range and uses the word ''must,'' which overstates what confidence intervals imply.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230P0MQ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A water tank initially contains 47 gallons of water. Water drains from the tank at a constant rate of 3 gallons per minute. Which function $f(t)$ gives the amount of water, in gallons, remaining in the tank $t$ minutes after draining begins?', NULL, $lyceon_json$[{"key":"A","text":"$f(t) = 47 - 3t$"},{"key":"B","text":"$f(t) = 47 + 3t$"},{"key":"C","text":"$f(t) = 3t - 47$"},{"key":"D","text":"$f(t) = 47 - \\frac{t}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The tank starts at 47 gallons and loses 3 gallons each minute, so the amount remaining after $t$ minutes is $f(t) = 47 - 3t$. The expression $47 + 3t$ incorrectly adds water over time instead of subtracting, a sign error that ignores the draining. The expression $3t - 47$ reverses the roles of the initial amount and the rate term, which would yield negative values immediately and does not model the situation. The expression $47 - \\frac{t}{3}$ uses the reciprocal of the rate, confusing 3 gallons per minute with 1 gallon every 3 minutes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23CJSYS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set contains $11$ values. The mean of the data set is $46$ and the median is $39$. If each value in the data set is first multiplied by $3$ and then $7$ is added to the result, what are the new mean and new median?', NULL, $lyceon_json$[{"key":"A","text":"Mean: $138$, Median: $117$"},{"key":"B","text":"Mean: $145$, Median: $117$"},{"key":"C","text":"Mean: $145$, Median: $124$"},{"key":"D","text":"Mean: $159$, Median: $124$"}]$lyceon_json$::jsonb, 'C', NULL, E'When every value is transformed by $f(x) = 3x + 7$, both the mean and median undergo the same linear transformation. The new mean is $3(46) + 7 = 138 + 7 = 145$, and the new median is $3(39) + 7 = 117 + 7 = 124$. The values $138$ and $117$ result from multiplying by $3$ but omitting the addition of $7$ for both measures — an incomplete application of the transformation. Mean $145$ with median $117$ reflects the misconception that adding a constant affects only the mean and not the median. Mean $159$ with median $124$ arises from incorrectly computing $(46 + 7) \\times 3 = 159$, reversing the order of operations for the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24B9JEL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $7$ cups of oats for every $3$ cups of almonds. If a baker uses $28$ cups of oats, how many cups of almonds are needed?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$12$"},{"key":"C","text":"$21$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of oats to almonds is $7:3$. Setting up the proportion $\\frac{7}{3} = \\frac{28}{x}$ and solving gives $x = \\frac{28 \\times 3}{7} = 12$. The answer $4$ results from dividing $28 \\div 7 = 4$, which gives the scale factor rather than the number of cups of almonds. The answer $21$ comes from subtracting $28 - 7 = 21$, which incorrectly treats the relationship as additive rather than multiplicative. The answer $84$ results from computing $28 \\times 3 = 84$ without dividing by $7$, applying only half of the proportion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24MAKX6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = 2^{x-3} + 5$. Which of the following describes the range of $h$?', NULL, $lyceon_json$[{"key":"A","text":"All real numbers greater than $5$"},{"key":"B","text":"All real numbers greater than or equal to $5$"},{"key":"C","text":"All real numbers greater than $3$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'The base exponential $2^{x-3}$ is always positive for all real $x$, approaching $0$ as $x \\to -\\infty$ but never equaling $0$. Adding $5$ shifts the output up by $5$, so $h(x) > 5$ for all $x$, but $h(x)$ never equals $5$. Therefore the range is all real numbers greater than $5$. The choice stating greater than or equal to $5$ incorrectly includes $5$, which would require $2^{x-3} = 0$, an impossibility for exponential functions. The choice stating greater than $3$ confuses the horizontal shift parameter with the range. The choice stating all real numbers ignores that exponential functions with a positive base always produce positive outputs, making values at or below $5$ unreachable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM253BNVF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A trapezoid has parallel bases of length $13$ and $19$ and a height of $7$. What is the area of the trapezoid?', NULL, $lyceon_json$[{"key":"A","text":"$91$"},{"key":"B","text":"$98$"},{"key":"C","text":"$112$"},{"key":"D","text":"$224$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $112$. The area of a trapezoid is $\\frac{1}{2}(b_1 + b_2)(h) = \\frac{1}{2}(13 + 19)(7) = \\frac{1}{2}(32)(7) = 112$. The value $91$ results from using only the shorter base ($13 \\times 7 = 91$) rather than the average of both bases. The value $98$ comes from an arithmetic slip when adding the bases, computing $13 + 19 = 28$ instead of $32$, which gives $\\frac{1}{2}(28)(7) = 98$. The value $224$ results from omitting the factor of $\\frac{1}{2}$ in the trapezoid area formula, computing $(32)(7) = 224$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25RKTHF', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A workshop produces chairs and tables. Each chair requires $3$ hours of labor and $4$ kilograms of wood. Each table requires $5$ hours of labor and $7$ kilograms of wood. The workshop has at most $47$ hours of labor and at most $53$ kilograms of wood available per week. If the workshop produces $9$ chairs in a week, what is the maximum number of whole tables it can produce that same week?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$4$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $t$ be the number of tables. The labor constraint is $3(9) + 5t \\leq 47$, which simplifies to $27 + 5t \\leq 47$, giving $t \\leq 4$. The wood constraint is $4(9) + 7t \\leq 53$, which simplifies to $36 + 7t \\leq 53$, giving $7t \\leq 17$, so $t \\leq \\frac{17}{7} \\approx 2.43$. Since both constraints must hold simultaneously and $t$ must be a whole number, the maximum is $2$. The value $3$ results from rounding $\\frac{17}{7}$ up to $3$ instead of down, an arithmetic error in applying the integer constraint. The value $4$ comes from checking only the labor constraint and ignoring the wood constraint entirely. The value $7$ comes from ignoring the chairs altogether and dividing the total wood by the per-table wood requirement, misreading what the problem asks.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM280YUK5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'What is the radius of the circle defined by the equation $x^2 + y^2 + 10x - 18y + 42 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{42}$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$64$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $8$. Completing the square: group terms as $(x^2 + 10x) + (y^2 - 18y) = -42$. Completing the square for $x$: $(x + 5)^2 - 25$. Completing the square for $y$: $(y - 9)^2 - 81$. Substituting: $(x + 5)^2 + (y - 9)^2 = -42 + 25 + 81 = 64$. Therefore $r^2 = 64$ and $r = 8$. The value $\\sqrt{42}$ comes from incorrectly treating the constant term $42$ as $r^2$. The value $6$ results from an arithmetic slip when computing $-42 + 25 + 81$, obtaining $36$ instead of $64$. The value $64$ comes from finding $r^2 = 64$ but not taking the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28ITELE', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$5x - 3y = 11$$ $$2x + 7y = 29$$ What is the value of $x + y$ for the solution $(x, y)$ to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying the first equation by $7$ gives $35x - 21y = 77$. Multiplying the second equation by $3$ gives $6x + 21y = 87$. Adding these eliminates $y$: $41x = 164$, so $x = 4$. Substituting into $2(4) + 7y = 29$ gives $7y = 21$, so $y = 3$. Therefore $x + y = 7$. The value $1$ results from computing $x - y = 4 - 3$ instead of $x + y$, misreading the question. The value $4$ comes from finding $x$ but stopping before adding $y$, an incomplete solution. The value $11$ comes from confusing the right-hand side of the first equation with the requested quantity.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28PQMXQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 2x^2 - 20x + 53$. The function $g$ is defined by $g(x) = f(x + 3) - 7$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, rewrite $f(x)$ in vertex form by completing the square: $f(x) = 2(x^2 - 10x) + 53 = 2(x^2 - 10x + 25 - 25) + 53 = 2(x - 5)^2 - 50 + 53 = 2(x - 5)^2 + 3$. The minimum value of $f$ is $3$. Now, $g(x) = f(x + 3) - 7 = 2((x + 3) - 5)^2 + 3 - 7 = 2(x - 2)^2 - 4$. Since $(x - 2)^2 \\geq 0$, the minimum of $g$ is $-4$, occurring at $x = 2$. The distractor $3$ comes from finding the minimum of $f$ without applying the vertical shift of $-7$. The distractor $-7$ results from assuming the minimum of $f$ is $0$ and only applying the $-7$ shift. The distractor $4$ results from a sign error, computing $-3 + 7 = 4$ instead of $3 - 7 = -4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AODIF3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $400$ residents of a town with $12{,}000$ residents and finds that $34\\%$ of the sample supports a new park. The margin of error for the survey is $\\pm 4.7$ percentage points. Based on this information, which of the following is a plausible estimate for the number of residents in the entire town who support the new park?', NULL, $lyceon_json$[{"key":"A","text":"$2{,}880$"},{"key":"B","text":"$3{,}516$"},{"key":"C","text":"$4{,}920$"},{"key":"D","text":"$5{,}400$"}]$lyceon_json$::jsonb, 'B', NULL, E'The plausible range for the population proportion is $34\\% \\pm 4.7\\%$, which is $29.3\\%$ to $38.7\\%$. Applying this to $12{,}000$ residents gives a range of $0.293 \\times 12{,}000 = 3{,}516$ to $0.387 \\times 12{,}000 = 4{,}644$. The value $3{,}516$ falls at the lower bound and is plausible. The value $2{,}880$ equals $0.24 \\times 12{,}000$, which is below the confidence interval — this results from subtracting the margin of error twice or using $24\\%$. The value $4{,}920$ equals $0.41 \\times 12{,}000$, which exceeds the upper bound of $38.7\\%$ and falls outside the plausible range. The value $5{,}400$ equals $0.45 \\times 12{,}000$, well above the interval, resulting from adding the margin of error to the proportion incorrectly as $34 + 4.7 + 4.7 \\approx 43\\%$ or similar arithmetic error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AVM53G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set of $9$ values has a mean of $42$. When the value $78$ is removed from the data set, what is the mean of the remaining $8$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '37.5', ARRAY['75/2', '37.5'], E'The sum of all $9$ values is $9 \\times 42 = 378$. After removing the value $78$, the sum of the remaining $8$ values is $378 - 78 = 300$. The new mean is $\\frac{300}{8} = 37.5$. A common error is to subtract $78$ directly from the mean, giving $42 - 78 = -36$, which misapplies the relationship between individual values and the mean. Another error is to divide by $9$ instead of $8$ after removing the value, giving $\\frac{300}{9} \\approx 33.3$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BCE1EV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is formed by attaching a hemisphere to one end of a right circular cylinder. The radius of both the cylinder and the hemisphere is $6$ cm, and the total height of the solid (from the base of the cylinder to the top of the hemisphere) is $23$ cm. What is the total volume of the solid, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$756\\pi$"},{"key":"B","text":"$828\\pi$"},{"key":"C","text":"$900\\pi$"},{"key":"D","text":"$972\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $756\\pi$. The hemisphere has radius $6$, so its height is $6$ cm. The cylinder height is $23 - 6 = 17$ cm. The cylinder volume is $\\pi(6^2)(17) = 612\\pi$. The hemisphere volume is $\\frac{2}{3}\\pi(6^3) = \\frac{2}{3}\\pi(216) = 144\\pi$. The total volume is $612\\pi + 144\\pi = 756\\pi$. The value $828\\pi$ results from using the full height $23$ for the cylinder and ignoring the hemisphere entirely: $\\pi(36)(23) = 828\\pi$. The value $900\\pi$ comes from using a full sphere instead of a hemisphere: $612\\pi + \\frac{4}{3}\\pi(216) = 612\\pi + 288\\pi = 900\\pi$. The value $972\\pi$ results from using the full height $23$ for the cylinder and then also adding the hemisphere: $828\\pi + 144\\pi = 972\\pi$, double-counting the hemisphere''s height.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C2OLMW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In a triangle, two sides have lengths $7$ and $8$, and the included angle measures $120^\\circ$. What is the length of the third side?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{57}$"},{"key":"B","text":"$\\sqrt{113}$"},{"key":"C","text":"$13$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $13$. Using the Law of Cosines: $c^2 = 7^2 + 8^2 - 2(7)(8)\\cos(120^\\circ)$. Since $\\cos(120^\\circ) = -\\frac{1}{2}$, this becomes $c^2 = 49 + 64 - 2(7)(8)(-\\frac{1}{2}) = 113 + 56 = 169$, so $c = 13$. The answer $\\sqrt{57}$ results from a sign error: using $\\cos(60^\\circ) = \\frac{1}{2}$ instead of $\\cos(120^\\circ) = -\\frac{1}{2}$, which gives $113 - 56 = 57$. The answer $\\sqrt{113}$ comes from omitting the $-2ab\\cos(C)$ cross term entirely and computing only $a^2 + b^2 = 113$. The answer $15$ results from misapplying the cosine value as $-1$ instead of $-\\frac{1}{2}$, yielding $113 + 112 = 225 = 15^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CL6NHV', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $8x - 31 = 41$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$\\frac{5}{4}$"},{"key":"C","text":"$9$"},{"key":"D","text":"$72$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $31$ to both sides gives $8x = 72$, and dividing both sides by $8$ gives $x = 9$. The value $-9$ results from a sign error, applying the negative of the correct answer. The value $\\frac{5}{4}$ results from subtracting $31$ from $41$ instead of adding, yielding $8x = 10$ and $x = \\frac{10}{8} = \\frac{5}{4}$. The value $72$ results from stopping after finding $8x = 72$ without dividing by $8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CXFSPI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the hypotenuse has length $19$ and one of the acute angles measures $30^\\circ$. What is the length of the side opposite the $30^\\circ$ angle?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{2}$"},{"key":"B","text":"$\\frac{19\\sqrt{3}}{2}$"},{"key":"C","text":"$19\\sqrt{3}$"},{"key":"D","text":"$\\frac{19\\sqrt{2}}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{19}{2}$. In a 30-60-90 triangle, the side opposite $30^\\circ$ is half the hypotenuse. Therefore the side is $\\frac{19}{2}$. The value $\\frac{19\\sqrt{3}}{2}$ is the side adjacent to $30^\\circ$ (opposite $60^\\circ$), not the side opposite $30^\\circ$, which reflects a misread of which side was requested. The value $19\\sqrt{3}$ results from incorrectly multiplying the hypotenuse by $\\sqrt{3}$ rather than dividing by $2$, confusing the 30-60-90 ratios. The value $\\frac{19\\sqrt{2}}{2}$ results from applying the 45-45-90 triangle ratio instead of the 30-60-90 ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DIRF5H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A salesperson earns a base monthly salary plus a commission of $8\\%$ on all sales exceeding $4{,}500$ dollars. In March, the salesperson''s total earnings were $3{,}100$ dollars and total sales were $11{,}750$ dollars. What is the salesperson''s base monthly salary, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$2{,}160$"},{"key":"B","text":"$2{,}520$"},{"key":"C","text":"$2{,}740$"},{"key":"D","text":"$3{,}100$"}]$lyceon_json$::jsonb, 'B', NULL, E'The commission applies only to sales above $4{,}500$ dollars. The commissionable amount is $11{,}750 - 4{,}500 = 7{,}250$ dollars, and the commission earned is $0.08 \\times 7{,}250 = 580$ dollars. The base salary is $3{,}100 - 580 = 2{,}520$ dollars. The value $2{,}160$ results from computing $8\\%$ of the full $11{,}750$ in sales ($0.08 \\times 11{,}750 = 940$) without subtracting the threshold, then $3{,}100 - 940 = 2{,}160$. The value $2{,}740$ results from applying $8\\%$ to the threshold amount itself ($0.08 \\times 4{,}500 = 360$), then $3{,}100 - 360 = 2{,}740$, reversing which portion earns commission. The value $3{,}100$ treats the total earnings as the base salary, ignoring the commission entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E8MWXM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 11x - 29$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$-15$"},{"key":"B","text":"$-14$"},{"key":"C","text":"$15$"},{"key":"D","text":"$73$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 4$ gives $f(4) = 11(4) - 29 = 44 - 29 = 15$. The value $-15$ results from a sign error, negating the correct answer. The value $-14$ results from an arithmetic slip of adding $11 + 4 = 15$ instead of multiplying $11 \\times 4 = 44$, then computing $15 - 29 = -14$. The value $73$ comes from adding $29$ instead of subtracting it, giving $44 + 29 = 73$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H3Y1P7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'If $\\sin(\\theta) = \\frac{7}{25}$ where $0 < \\theta < \\frac{\\pi}{2}$, what is the value of $\\cos(\\theta)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24/25', ARRAY['24/25', '0.96', '.96'], E'The correct answer is $\\frac{24}{25}$. Since $\\sin(\\theta) = \\frac{7}{25}$, the side opposite $\\theta$ is $7$ and the hypotenuse is $25$. Using the Pythagorean identity $\\sin^2(\\theta) + \\cos^2(\\theta) = 1$, we get $\\cos^2(\\theta) = 1 - \\frac{49}{625} = \\frac{576}{625}$. Since $\\theta$ is in the first quadrant, $\\cos(\\theta) = \\frac{24}{25}$. Alternatively, the adjacent side is $\\sqrt{25^2 - 7^2} = \\sqrt{576} = 24$, so $\\cos(\\theta) = \\frac{24}{25}$. A common error is computing $\\sqrt{625 - 49}$ incorrectly, and another is forgetting to take the square root at the final step, yielding $\\frac{576}{625}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H4HMTE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'In the equation $7x - 3y = 29$, if $x = 5$, what is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Substituting $x = 5$ into the equation gives $7(5) - 3y = 29$, which simplifies to $35 - 3y = 29$. Subtracting $35$ from both sides yields $-3y = -6$, and dividing by $-3$ gives $y = 2$. A common error is a sign mistake when isolating $y$, such as obtaining $y = -2$ by dividing $-6$ by $3$ instead of $-3$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HCYZCV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'An exterior angle of a triangle measures $139^\\circ$. One of the two non-adjacent interior angles of the triangle measures $53^\\circ$. What is the measure, in degrees, of the other non-adjacent interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$41^\\circ$"},{"key":"B","text":"$86^\\circ$"},{"key":"C","text":"$94^\\circ$"},{"key":"D","text":"$127^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $86^\\circ$. By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $139 = 53 + x$, giving $x = 86$. The answer $41^\\circ$ comes from finding the adjacent interior angle ($180 - 139 = 41$) and stopping there, which is an incomplete solution. The answer $94^\\circ$ results from an arithmetic slip when subtracting $53$ from $139$ (for example, computing $139 - 53 = 94$ instead of $86$ by mishandling the subtraction). The answer $127^\\circ$ comes from incorrectly subtracting only the known interior angle from $180^\\circ$ ($180 - 53 = 127$), ignoring the exterior angle relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J4H55X', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What value of $x$ satisfies the equation $$3(4x - 5) - 2(3x + 7) = 5x - 6\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$-35$"},{"key":"B","text":"$2$"},{"key":"C","text":"$13$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing gives $12x - 15 - 6x - 14 = 5x - 6$. Combining like terms on the left yields $6x - 29 = 5x - 6$. Subtracting $5x$ from both sides and adding $29$ gives $x = 23$. The value $2$ arises from a sign error in distributing $-2$ over $(3x + 7)$, incorrectly obtaining $-6x + 7$ instead of $-6x - 14$, which leads to $6x - 8 = 5x - 6$ and $x = 2$. The value $13$ comes from incomplete distribution of $3$ over $(4x - 5)$, treating the result as $12x - 5$ instead of $12x - 15$, yielding $6x - 19 = 5x - 6$ and $x = 13$. The value $-35$ results from an arithmetic slip when transposing $-29$, subtracting $29$ on the right instead of adding it, giving $x = -6 - 29 = -35$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JV3CZH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles of a triangle measure $47^\\circ$ and $68^\\circ$. What is the measure, in degrees, of the third angle?', NULL, $lyceon_json$[{"key":"A","text":"$55^\\circ$"},{"key":"B","text":"$65^\\circ$"},{"key":"C","text":"$75^\\circ$"},{"key":"D","text":"$115^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $65^\\circ$. The sum of the interior angles of any triangle is $180^\\circ$. Subtracting the two known angles: $180 - 47 - 68 = 65$. The answer $55^\\circ$ results from an arithmetic slip when computing $180 - 47 - 68$ (e.g., miscalculating $47 + 68$ as $125$ instead of $115$). The answer $75^\\circ$ comes from another arithmetic slip such as computing $47 + 68 = 105$. The answer $115^\\circ$ results from misreading the question and reporting the sum of the two given angles rather than the third angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KFOPVN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $72$ dollars is on sale for $54$ dollars. What is the percent decrease in price?', NULL, $lyceon_json$[{"key":"A","text":"$18\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$33\\%$"},{"key":"D","text":"$75\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The decrease in price is $72 - 54 = 18$ dollars. The percent decrease is $\\frac{18}{72} \\times 100 = 25\\%$. The value $18\\%$ confuses the dollar amount of the decrease with the percent decrease. The value $33\\%$ results from dividing the decrease by the sale price instead of the original price: $\\frac{18}{54} \\approx 33\\%$. The value $75\\%$ computes $\\frac{54}{72} = 75\\%$, which is the percent of the original price that remains, not the percent decrease.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KRGSCJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $g$ is defined by $g(x) = (x - 7)^2 + 4$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'The function $g(x) = (x - 7)^2 + 4$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, $h = 7$, and $k = 4$. Since the coefficient of the squared term is positive, the parabola opens upward and the vertex represents the minimum. The minimum value is $k = 4$, occurring at $x = 7$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LBFIEI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $7$ members of a hiking club are listed below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LEL36K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $13$ red marbles, $9$ blue marbles, and $5$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{9}$"},{"key":"B","text":"$\\frac{9}{27}$"},{"key":"C","text":"$\\frac{9}{22}$"},{"key":"D","text":"$\\frac{9}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $13 + 9 + 5 = 27$. The probability of selecting a blue marble is $\\frac{9}{27}$, which simplifies to $\\frac{1}{3}$. The value $\\frac{1}{9}$ results from confusing the count of blue marbles with the total. The value $\\frac{9}{22}$ results from miscounting the total as $22$ by omitting the green marbles. The value $\\frac{9}{13}$ results from using only the red marble count as the denominator instead of the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MFL8G8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 + 2x - 63 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factor the quadratic: $x^2 + 2x - 63 = (x + 9)(x - 7) = 0$. Setting each factor to zero gives $x = -9$ or $x = 7$. Since the problem requires $x > 0$, the answer is $7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MOK7X4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $$\\frac{3(2x - 7)}{4} = 9\\;?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9.5', ARRAY['19/2', '9.5'], E'Multiply both sides by $4$ to get $3(2x - 7) = 36$. Distribute the $3$ to get $6x - 21 = 36$. Add $21$ to both sides: $6x = 57$. Divide by $6$: $x = \\frac{57}{6} = 9.5$. A common error is forgetting to distribute the $3$ before dividing, or mishandling the fraction by multiplying only the numerator term by $4$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N6FLPD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scientist models the relationship between temperature in degrees Celsius, $x$, and reaction rate in moles per second, $y$, using the equation $y = 0.042x + 0.15$. At a temperature of $35°\\text{C}$, the observed reaction rate is $1.74$ moles per second. What is the residual for this observation, and what does it indicate?', NULL, $lyceon_json$[{"key":"A","text":"$-0.12$; the model overpredicted the reaction rate at this temperature."},{"key":"B","text":"$0.12$; the observed reaction rate is greater than the rate predicted by the model."},{"key":"C","text":"$0.12$; the model overpredicted the reaction rate at this temperature."},{"key":"D","text":"$1.62$; the observed reaction rate is greater than the rate predicted by the model."}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted value at $x = 35$ is $y = 0.042(35) + 0.15 = 1.47 + 0.15 = 1.62$. The residual is defined as observed minus predicted: $1.74 - 1.62 = 0.12$. A positive residual means the observed value exceeds the prediction, so the model underpredicted at this temperature. The value $-0.12$ results from computing predicted minus observed instead of observed minus predicted, reversing the sign. The option stating $0.12$ with the claim that the model overpredicted has the correct residual magnitude but contradicts what a positive residual means: a positive residual indicates underprediction, not overprediction. The value $1.62$ is the predicted value itself, not the residual, and reflects stopping the calculation before subtracting from the observed value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N6METQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher randomly selects $300$ students from the university and surveys them about their weekly exercise hours and their GPA. The researcher finds that students who exercise more than $5$ hours per week have higher GPAs on average than students who exercise fewer than $2$ hours per week. Which of the following conclusions is best supported by this study design?', NULL, $lyceon_json$[{"key":"A","text":"Exercising more than $5$ hours per week causes students at this university to have higher GPAs."},{"key":"B","text":"There is an association between weekly exercise hours and GPA among students at this university."},{"key":"C","text":"Exercising more than $5$ hours per week causes all college students to have higher GPAs."},{"key":"D","text":"There is an association between weekly exercise hours and GPA among all college students."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study (no random assignment to exercise levels), so it can establish association but not causation. The sample was randomly selected from the university, so findings generalize to that university''s population but not to all college students. The claim that exercise causes higher GPAs at this university incorrectly infers causation from an observational study. The claim about causing higher GPAs among all college students both infers causation and overgeneralizes beyond the sampled population. The claim of association among all college students correctly avoids causation but overgeneralizes beyond the university from which the sample was drawn.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NP79ZY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The equation $x^2 + y^2 - 8x + 2y = k$ defines a circle that passes through the point $(11, 5)$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '68', ARRAY['68'], E'The correct answer is $68$. Substituting $(11, 5)$ into the equation: $11^2 + 5^2 - 8(11) + 2(5) = 121 + 25 - 88 + 10 = 68$. Therefore $k = 68$. A common error is miscomputing $8 \\times 11 = 88$, for example obtaining $80$ or $98$, which would yield an incorrect value of $k$. Another error is applying the wrong sign to one of the terms, such as adding $88$ instead of subtracting it.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NQ7UKR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the slope of the line that passes through the points $(-3, 11)$ and $(5, -13)$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-\\frac{1}{3}$"},{"key":"C","text":"$\\frac{1}{3}$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope formula gives $m = \\frac{-13 - 11}{5 - (-3)} = \\frac{-24}{8} = -3$. The value $-\\frac{1}{3}$ results from inverting the slope formula, computing the change in $x$ over the change in $y$ (run over rise) instead of rise over run. The value $\\frac{1}{3}$ compounds that inversion error with a sign error, losing the negative. The value $3$ results from dropping the negative sign from the correct calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OYQNJD', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 11x + 28}{x^2 - 49} \\cdot \\frac{x + 7}{x - 1}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 4}{x - 1}$"},{"key":"B","text":"$\\frac{x + 4}{x + 1}$"},{"key":"C","text":"$\\frac{x - 4}{x + 7}$"},{"key":"D","text":"$\\frac{x - 7}{x - 1}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor each polynomial: $x^2 - 11x + 28 = (x - 4)(x - 7)$ and $x^2 - 49 = (x - 7)(x + 7)$. The expression becomes $\\frac{(x - 4)(x - 7)}{(x - 7)(x + 7)} \\cdot \\frac{x + 7}{x - 1}$. Cancel $(x - 7)$ in the numerator and denominator, then cancel $(x + 7)$, yielding $\\frac{x - 4}{x - 1}$. The distractor $\\frac{x + 4}{x + 1}$ results from sign errors in the factoring, flipping the signs within both binomials. The distractor $\\frac{x - 4}{x + 7}$ comes from only cancelling $(x - 7)$ and not proceeding to multiply by $\\frac{x + 7}{x - 1}$. The distractor $\\frac{x - 7}{x - 1}$ reflects incorrectly cancelling $(x - 4)$ with $(x - 7)$ while retaining the wrong factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PB9WO3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ employees at a company recorded whether each employee works remotely or on-site and whether each uses public transit or drives. Of the $200$ employees, $74$ work remotely, $126$ work on-site, $53$ of the on-site employees drive, and $29$ of the remote employees use public transit. If one employee is selected at random from those who use public transit, what is the probability that this employee works on-site?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{73}{200}$"},{"key":"B","text":"$\\frac{73}{126}$"},{"key":"C","text":"$\\frac{73}{102}$"},{"key":"D","text":"$\\frac{29}{102}$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, determine the number of on-site employees who use public transit: $126 - 53 = 73$. The total number of public transit users is $73 + 29 = 102$. The conditional probability that an employee works on-site given that they use public transit is $\\frac{73}{102}$. The value $\\frac{73}{200}$ incorrectly uses the total number of employees as the denominator rather than conditioning on transit users. The value $\\frac{73}{126}$ uses only the on-site count as the denominator, ignoring the condition. The value $\\frac{29}{102}$ gives the probability of being a remote transit user, answering the reverse of what was asked.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PXZ0KA', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$3x + 2y = 19$$ $$x - 2y = -7$$ What is the value of $y$ in the solution to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Adding the two equations eliminates $y$: $(3x + 2y) + (x - 2y) = 19 + (-7)$, which gives $4x = 12$, so $x = 3$. Substituting $x = 3$ into the second equation: $3 - 2y = -7$, so $-2y = -10$, and $y = 5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QHVS1Z', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A mechanic charges a flat diagnostic fee plus an hourly labor rate for every repair. The total charge for a 3-hour repair is 289 dollars, and the total charge for a 7-hour repair is 513 dollars. The mechanic then increases the flat fee by 15 dollars and decreases the hourly rate by 4 dollars. Under the new pricing, what is the total charge, in dollars, for a 5-hour repair?', NULL, $lyceon_json$[{"key":"A","text":"$381$"},{"key":"B","text":"$396$"},{"key":"C","text":"$401$"},{"key":"D","text":"$416$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $r$ be the hourly rate and $f$ be the flat fee. From the given information, $3r + f = 289$ and $7r + f = 513$. Subtracting the first equation from the second gives $4r = 224$, so $r = 56$. Substituting back yields $f = 289 - 3(56) = 289 - 168 = 121$. The new rate is $56 - 4 = 52$ dollars per hour and the new flat fee is $121 + 15 = 136$ dollars. For a 5-hour repair: $52(5) + 136 = 260 + 136 = 396$ dollars. The value $381$ results from applying only the rate decrease while keeping the original flat fee: $52(5) + 121 = 381$. The value $401$ results from using the original pricing without any adjustments: $56(5) + 121 = 401$. The value $416$ results from applying only the fee increase while keeping the original hourly rate: $56(5) + 136 = 416$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ROQP7A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to test whether a new tutoring method improves test scores compared to the standard method. They recruit $180$ students from three high schools ($60$ per school). At each school, $30$ students are randomly assigned to the new method and $30$ to the standard method. After $12$ weeks, scores are compared. A student points out that all three schools are in the same suburban district with similar demographics. Which of the following is the most significant limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"The study lacks random assignment, so it cannot establish causation."},{"key":"B","text":"The sample size of $180$ students is too small to detect any difference in test scores."},{"key":"C","text":"Because the schools share similar demographics, the results may not generalize to students in substantially different settings."},{"key":"D","text":"The $12$-week duration is too short for tutoring to have any measurable effect on test scores."}]$lyceon_json$::jsonb, 'C', NULL, E'The study does use random assignment within each school, so it can establish causation for the population it represents. However, because all three schools are in the same suburban district with similar demographics, the findings may not generalize to students in different types of schools or districts (e.g., urban or rural, different socioeconomic backgrounds). The claim that the study lacks random assignment is factually incorrect — students were randomly assigned to treatment groups within each school. The claim that $180$ students is too small is not the most significant limitation; $180$ is a reasonable sample size for detecting moderate effects, and sample size alone is not the concern raised by the student''s observation. The claim that $12$ weeks is too short makes an unsupported assumption about the minimum time needed for tutoring effects, which is not the limitation highlighted by the demographic similarity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RSHSVM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In triangle PQR, $PQ = 10$ and $QR = 17$. The altitude from $Q$ to side $\\overline{PR}$ has length $8$, and its foot $H$ lies between $P$ and $R$. What is the area of triangle PQR?', NULL, $lyceon_json$[{"key":"A","text":"$60$"},{"key":"B","text":"$84$"},{"key":"C","text":"$85$"},{"key":"D","text":"$168$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $84$. The altitude $QH = 8$ creates two right triangles. In right triangle $PQH$: $PH = \\sqrt{10^2 - 8^2} = \\sqrt{36} = 6$. In right triangle $QHR$: $HR = \\sqrt{17^2 - 8^2} = \\sqrt{225} = 15$. So $PR = PH + HR = 6 + 15 = 21$. The area is $\\frac{1}{2}(21)(8) = 84$. The value $60$ results from using only the segment $HR = 15$ as the base, computing $\\frac{1}{2}(15)(8) = 60$, which accounts for only part of the triangle. The value $85$ comes from incorrectly using $PQ$ and $QR$ as base and height: $\\frac{1}{2}(10)(17) = 85$, but these are not perpendicular. The value $168$ results from omitting the factor of $\\frac{1}{2}$ in the area formula, computing $21 \\times 8 = 168$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SOYED3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A student is ordering custom pins for a school event. Each pin costs $7$ dollars and there is a flat shipping fee of $11$ dollars. If the student has at most $53$ dollars to spend, what is the greatest number of pins the student can order?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Let $n$ represent the number of pins. The total cost is $7n + 11$, and this must be at most $53$: $$7n + 11 \\leq 53.$$ Subtracting $11$ from both sides gives $7n \\leq 42$. Dividing both sides by $7$ gives $n \\leq 6$. Since $n$ must be a whole number, the greatest number of pins is $6$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T3C9TT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylindrical tank has a diameter of $14$ feet and a height of $9$ feet. Water fills the tank to a height of $5$ feet. What fraction of the tank''s total volume is filled with water?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/9', ARRAY['5/9', '0.555', '.555', '0.556', '.556'], E'The correct answer is $\\frac{5}{9}$. The tank is a cylinder with radius $7$ feet and height $9$ feet, so its total volume is $\\pi(7^2)(9) = 441\\pi$ cubic feet. The water fills the cylinder to a height of $5$ feet, so the water volume is $\\pi(7^2)(5) = 245\\pi$ cubic feet. The fraction filled is $\\frac{245\\pi}{441\\pi} = \\frac{5}{9}$. Since both the full tank and the water share the same circular cross-section, the fraction simplifies to the ratio of the water height to the total height. A common error is using the diameter $14$ as the radius when computing volumes, but since the radius cancels, this does not affect the ratio. Another error is computing $\\frac{5}{14}$, confusing the diameter with the height.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TKZNEX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'The line of best fit for a set of data is given by $y = 2.3x + 11$. What is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '31.7', ARRAY['31.7'], E'Substituting $x = 9$ into the equation gives $y = 2.3(9) + 11 = 20.7 + 11 = 31.7$. A common error is to forget to add the $y$-intercept, giving $20.7$ instead of $31.7$. Another error is to compute $2.3 + 9 + 11 = 22.3$, adding the values instead of multiplying the slope by the $x$-value.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TOQFSE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'The equation of a circle is $(x + 11)^2 + (y - 4)^2 = 81$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$9$"},{"key":"C","text":"$11$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $9$. The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, so $r^2 = 81$ and $r = 9$. The value $4$ comes from misreading the equation and extracting the constant from the $y$-term as the radius. The value $11$ results from confusing the $x$-coordinate of the center with the radius. The value $81$ comes from identifying $r^2 = 81$ but not taking the square root to find $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UR8873', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A solution is prepared by mixing chemical A and chemical B in a volume ratio of $5:3$. Chemical A has a density of $1.2$ grams per milliliter, and chemical B has a density of $0.9$ grams per milliliter. What is the ratio of the mass of chemical A to the mass of chemical B in the solution?', NULL, $lyceon_json$[{"key":"A","text":"$5:3$"},{"key":"B","text":"$4:3$"},{"key":"C","text":"$20:9$"},{"key":"D","text":"$9:20$"}]$lyceon_json$::jsonb, 'C', NULL, E'Mass equals volume times density. Taking $5$ units of volume for chemical A and $3$ units for chemical B, the mass of A is $5 \\times 1.2 = 6$ grams and the mass of B is $3 \\times 0.9 = 2.7$ grams. The ratio $6:2.7$ simplifies to $60:27 = 20:9$. The ratio $5:3$ incorrectly uses the volume ratio as the mass ratio, ignoring the different densities. The ratio $4:3$ uses only the density ratio $1.2:0.9 = 4:3$ without accounting for the different volumes. The ratio $9:20$ reverses the correct ratio, giving mass of B to mass of A instead of A to B.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"unit_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VOFUV9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 + x - 12$ and $y = 3x + 3$ intersect at two points. What is the sum of the $y$-coordinates of these two points of intersection?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$12$"},{"key":"C","text":"$18$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set the two expressions equal: $x^2 + x - 12 = 3x + 3$, which simplifies to $x^2 - 2x - 15 = 0$. Factoring gives $(x - 5)(x + 3) = 0$, so $x = 5$ or $x = -3$. Substituting into $y = 3x + 3$: when $x = 5$, $y = 18$; when $x = -3$, $y = -6$. The sum of the $y$-coordinates is $18 + (-6) = 12$. The distractor $2$ comes from computing the sum of the $x$-coordinates ($5 + (-3) = 2$) instead of the $y$-coordinates. The distractor $18$ results from finding only one intersection point and reporting its $y$-value. The distractor $24$ results from a sign error, computing $18 + 6 = 24$ instead of $18 + (-6) = 12$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WJBE7V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A store increases the price of an item by $15\\%$, and then offers a $15\\%$ discount on the new price. If the final price of the item is $58.65$ dollars, what was the original price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let the original price be $p$. After a $15\\%$ increase, the price becomes $1.15p$. After a $15\\%$ discount on that new price, the final price is $0.85 \\times 1.15p = 0.9775p$. Setting $0.9775p = 58.65$ gives $p = \\frac{58.65}{0.9775} = 60$. A common error is to assume the successive $15\\%$ increase and $15\\%$ decrease cancel out, yielding $58.65$ as the original price. Another error is to divide by $1.00$ instead of $0.9775$, not recognizing that the net effect of a $15\\%$ increase followed by a $15\\%$ decrease is a $2.25\\%$ overall decrease.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WW3KLY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$kx + 6y = 17$$ $$3x + 9y = 21$$ In the system of equations above, $k$ is a constant. If the system has no solution, what is the value of $k$ ?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$\\frac{9}{2}$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$\\frac{2}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system of two linear equations has no solution when the lines are parallel: the ratios of the coefficients of $x$ and $y$ are equal, but the ratio of the constants is different. Setting $\\frac{k}{3} = \\frac{6}{9}$ gives $\\frac{k}{3} = \\frac{2}{3}$, so $k = 2$. Checking the constants: $\\frac{17}{21} \\neq \\frac{2}{3}$ (since $\\frac{2}{3} = \\frac{14}{21}$), confirming the system has no solution when $k = 2$. The value $\\frac{9}{2}$ results from incorrectly setting $\\frac{k}{3} = \\frac{9}{6}$ instead of $\\frac{k}{3} = \\frac{6}{9}$, reversing the ratio of the $y$-coefficients. The value $-2$ introduces an erroneous negative sign when solving $\\frac{k}{3} = \\frac{2}{3}$. The value $\\frac{2}{3}$ is the simplified ratio $\\frac{6}{9}$ itself rather than the result of solving $\\frac{k}{3} = \\frac{2}{3}$ for $k$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XREIOK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'In a class of $40$ students, each student studies exactly one of three languages: French, German, or Mandarin. There are $17$ students studying French, $14$ studying German, and $9$ studying Mandarin. Of the French students, $6$ are seniors. Of the German students, $5$ are seniors. Of the Mandarin students, $2$ are seniors. A student is selected at random from the class. Given that the selected student is NOT a senior, what is the probability that this student studies German? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/3', ARRAY['1/3', '0.333', '.333'], E'The total number of seniors is $6 + 5 + 2 = 13$, so there are $40 - 13 = 27$ non-senior students. The number of non-senior German students is $14 - 5 = 9$. The conditional probability that a non-senior student studies German is $\\frac{9}{27} = \\frac{1}{3}$. A common error is to compute $\\frac{14}{40}$, which gives the unconditional probability of studying German without restricting to non-seniors. Another error is to subtract only the German seniors from the German total but divide by $40$ rather than $27$, giving $\\frac{9}{40}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XV4NGL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution to the equation $\\sqrt{3x + 4} = x - 2$?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$7$"},{"key":"C","text":"$0$ and $7$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $3x + 4 = (x - 2)^2 = x^2 - 4x + 4$. Rearranging: $x^2 - 7x = 0$, so $x(x - 7) = 0$, yielding $x = 0$ or $x = 7$. However, squaring can introduce extraneous solutions, so both must be checked. For $x = 0$: $\\sqrt{4} = 2$ but $0 - 2 = -2$, so $2 \\neq -2$ and $x = 0$ is extraneous. For $x = 7$: $\\sqrt{25} = 5$ and $7 - 2 = 5$, which checks. The only valid solution is $7$. The distractor $0$ is the extraneous root that fails the domain requirement (the right side must be non-negative). The distractor listing both $0$ and $7$ results from solving the quadratic correctly but failing to check for extraneous solutions. The distractor $-7$ results from a sign error when solving $x(x - 7) = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XWU0WZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A printer produces $43$ pages in $5$ minutes. At this constant rate, how many minutes will it take to print $301$ pages?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$30$"},{"key":"C","text":"$35$"},{"key":"D","text":"$43$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate is $\\frac{43 \\text{ pages}}{5 \\text{ minutes}}$. Since $301 \\div 43 = 7$, the printer needs $7$ groups of $5$ minutes, giving $7 \\times 5 = 35$ minutes. The value $7$ is the scale factor (how many groups of $43$ pages), not the time in minutes; stopping there reflects incomplete reasoning. The value $30$ results from an arithmetic error such as computing the scale factor as $6$ instead of $7$ and then multiplying $6 \\times 5$. The value $43$ arises from dividing $301 \\div 7 = 43$, confusing the number of pages per group with the time.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7IN9R', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following is the solution to the inequality $8x - 17 > 39$ ?', NULL, $lyceon_json$[{"key":"A","text":"$x > 7$"},{"key":"B","text":"$x > 56$"},{"key":"C","text":"$x < 7$"},{"key":"D","text":"$x > \\frac{11}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $17$ to both sides of $8x - 17 > 39$ gives $8x > 56$. Dividing both sides by $8$ yields $x > 7$. The result $x > 56$ comes from stopping at $8x > 56$ without dividing by $8$, returning an intermediate value. The inequality $x < 7$ reverses the direction of the inequality, reflecting a misunderstanding that dividing by a positive number flips the sign. The result $x > \\frac{11}{4}$ comes from subtracting $17$ from $39$ (getting $22$) rather than adding $17$ to $39$, then dividing $22$ by $8$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z97C3I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collected data on the number of hours of sunlight per day, $x$, and the height, in centimeters, of a plant after $30$ days, $y$. The line of best fit for the data is $y = 1.7x + 4.3$. Which of the following is the best interpretation of the slope $1.7$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight per day, the predicted height of the plant after $30$ days increases by $1.7$ centimeters."},{"key":"B","text":"For each additional centimeter of height, the plant receives $1.7$ more hours of sunlight per day."},{"key":"C","text":"A plant that receives no sunlight is predicted to have a height of $1.7$ centimeters after $30$ days."},{"key":"D","text":"The plant grows $1.7$ centimeters each day."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a linear model represents the predicted change in $y$ for each unit increase in $x$. Here, the slope $1.7$ means that for each additional hour of sunlight per day, the predicted plant height after $30$ days increases by $1.7$ centimeters. The interpretation that reverses the variables — stating that each additional centimeter of height corresponds to $1.7$ more hours of sunlight — swaps the roles of the independent and dependent variables. The claim that a plant with no sunlight has a height of $1.7$ centimeters confuses the slope with the $y$-intercept, which is $4.3$. The interpretation that the plant grows $1.7$ centimeters each day misidentifies the unit of the independent variable: $x$ represents hours of sunlight per day, not the number of days.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZAHZ8Q', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $5(x^2 + 3x - 2) - 3(x^2 - 4x + 7)$?', NULL, $lyceon_json$[{"key":"A","text":"$8x^2 + 27x - 31$"},{"key":"B","text":"$2x^2 + 3x - 31$"},{"key":"C","text":"$2x^2 + 27x - 31$"},{"key":"D","text":"$2x^2 + 27x + 11$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing the first term gives $5x^2 + 15x - 10$. Distributing the second term gives $-3x^2 + 12x - 21$. Combining like terms: $(5 - 3)x^2 = 2x^2$, $(15 + 12)x = 27x$, and $-10 + (-21) = -31$. The result is $2x^2 + 27x - 31$. The distractor $8x^2 + 27x - 31$ results from adding the $x^2$ coefficients as $5 + 3 = 8$ instead of subtracting. The distractor $2x^2 + 3x - 31$ results from a sign error when distributing $-3$ to $-4x$, yielding $-12x$ instead of $+12x$, so $15x - 12x = 3x$. The distractor $2x^2 + 27x + 11$ results from a sign error on the constant: treating $-3(+7)$ as $+21$ and computing $-10 + 21 = +11$ instead of $-10 - 21 = -31$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20WBP4U', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Yuki Tanaka, a marine geochemist at the University of Bergen ______ recently published findings suggesting that deep-sea hydrothermal vents along the Mid-Atlantic Ridge release significantly more methane than previous oceanographic models had predicted.', $lyceon_json$[{"key":"A","text":", recently published"},{"key":"B","text":"— recently published"},{"key":"C","text":"; recently published"},{"key":"D","text":"recently published"}]$lyceon_json$::jsonb, 'A', NULL, E'The nonrestrictive appositive ''a marine geochemist at the University of Bergen'' renames the subject ''Dr. Yuki Tanaka'' and must be set off by matching punctuation on both sides. Because the appositive opens with a comma after ''Tanaka,'' it must close with a comma before ''recently published.'' Closing the appositive with a dash creates a mismatched pair of punctuation marks, which violates standard conventions. A semicolon would incorrectly sever the subject from its predicate, splitting the sentence at the wrong point. Omitting punctuation entirely leaves the appositive unclosed, which disrupts the grammatical structure and obscures where the appositive ends and the predicate begins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW214FDPL', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary scholar, if accurate, would most effectively support the student''s claim?', E'A student argues in a literature seminar paper that Victorian novelist George Eliot used the provincial settings of her novels not merely as realistic backdrops but as deliberate rhetorical instruments for critiquing the moral limitations of London-centered English society. The student contends that Eliot''s detailed depictions of rural communities reveal ethical complexities that the metropolitan characters in her fiction consistently fail to perceive.', $lyceon_json$[{"key":"A","text":"\"Eliot's Middlemarch portrays its small-town characters as possessing a moral awareness that her London visitors conspicuously lack, positioning the provinces as sites of ethical discernment rather than cultural backwardness.\""},{"key":"B","text":"\"Eliot drew heavily on her childhood memories of Warwickshire, and her provincial settings reflect an autobiographical impulse more than a programmatic social critique.\""},{"key":"C","text":"\"The realism of Eliot's rural descriptions earned her comparison to Dutch genre painters, whose meticulous attention to domestic detail she openly admired.\""},{"key":"D","text":"\"Eliot's later novels, particularly Daniel Deronda, shift decisively toward cosmopolitan London settings, suggesting that she eventually abandoned provincial subject matter.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The student claims that Eliot used provincial settings to critique London-centered society by revealing ethical complexities metropolitan characters miss. The quotation describing Middlemarch''s small-town characters as morally aware in contrast to London visitors directly supports this claim by illustrating provincial settings functioning as sites of ethical discernment. The quotation attributing Eliot''s provincial settings to autobiographical impulse rather than social critique directly contradicts the student''s argument. The quotation comparing Eliot''s realism to Dutch genre painting addresses her descriptive technique but not her use of provincial settings as rhetorical instruments for social critique. The quotation about Eliot abandoning provincial settings in later novels would undermine the student''s claim about a sustained rhetorical strategy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21IE8AJ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The geologist noted that the volcanic soil in the region was remarkably ______, supporting dense forests and abundant agriculture despite its proximity to an active caldera.', $lyceon_json$[{"key":"A","text":"fertile"},{"key":"B","text":"volatile"},{"key":"C","text":"conspicuous"},{"key":"D","text":"rigid"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes soil that supports dense forests and abundant agriculture, which directly indicates that the soil is productive for growing things. The word meaning productive for plant growth fits this context precisely. The word meaning likely to change rapidly or unpredictably relates to instability, not soil productivity. The word meaning easily noticeable describes visibility, not agricultural capacity. The word meaning stiff or inflexible describes physical properties unrelated to supporting plant life.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW229BOMB', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Mariana Veltri has documented that the cerambycid beetle Anoplophora glabripennis causes extensive damage to hardwood trees in urban environments. ______ cities such as Worcester, Massachusetts, have invested millions of dollars in programs to detect and remove infested trees before the beetles can spread to surrounding forests.', $lyceon_json$[{"key":"A","text":"For this reason,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence describes cities investing in beetle-removal programs as a direct consequence of the damage described in the first sentence. The transition "For this reason" correctly signals a cause-and-effect relationship. The option suggesting contrast ("In contrast") introduces an opposition that does not exist between the two sentences. The option "Specifically" implies the second sentence is a narrowing example of the first, but the second sentence describes a response to the problem, not a specific instance of it. The option "Meanwhile" implies simultaneity without causal connection, which misrepresents the logical relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22K8NB7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Political scientist Adaeze Obi studied legislative voting patterns across 23 parliamentary democracies and found that legislators from geographically large, sparsely populated districts broke with their party''s official position significantly more often than legislators from compact, densely populated urban districts. Obi proposes that this pattern reflects differing accountability structures: in large rural districts, legislators interact repeatedly with small, tightly knit constituent groups who track individual votes closely, creating pressure to prioritize local concerns over party directives. In dense urban districts, by contrast, individual voters have less personal access to their representative, and party brand recognition dominates electoral outcomes. However, Obi notes an important exception: in parliamentary systems where party leaders control candidate nomination lists, even rural legislators in large districts ________', $lyceon_json$[{"key":"A","text":"deviate from the party position at rates comparable to their urban counterparts, since defiance risks removal from the nomination list."},{"key":"B","text":"deviate from the party position more frequently than in other systems, since the nomination threat intensifies constituent pressure."},{"key":"C","text":"deviate at the same elevated rate as rural legislators in systems without leader-controlled nominations."},{"key":"D","text":"abandon their party affiliation entirely and run as independents in subsequent elections."}]$lyceon_json$::jsonb, 'A', NULL, E'Obi''s framework holds that rural legislators face constituent pressure to break with their party. When party leaders control nominations, a countervailing institutional pressure exists: defiance could cost the legislator their place on the ballot. This would logically suppress the rural deviation effect, bringing rural legislators'' rates closer to urban counterparts'' rates. The prediction that nomination control would intensify deviation contradicts the logic of the exception Obi introduces, which presents leader-controlled nominations as a constraining force. The prediction that rural legislators would deviate at the same elevated rate ignores the exception Obi explicitly flags, which implies that nomination control modifies the pattern rather than leaving it unchanged. The prediction that legislators would abandon their party entirely extrapolates far beyond the passage''s discussion of voting deviation rates into a dramatic action the text does not suggest.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22LKCE3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the 1970s, sociologist Harriet Zuckerman studied Nobel laureates in the sciences and found that their early career trajectories shared a striking commonality: nearly all had trained under previous Nobel winners or similarly elite mentors. Zuckerman argued that this pattern reflected not merely talent selection but an apprenticeship effect—working closely with eminent scientists exposed young researchers to tacit knowledge about identifying significant problems, designing decisive experiments, and navigating the social structures of scientific communities. Critics countered that elite mentors simply chose the most talented students, and that the students would have succeeded regardless. However, Zuckerman''s later follow-up work showed that comparably talented researchers who trained under non-eminent mentors published fewer landmark papers and received fewer major awards, suggesting that the apprenticeship effect operated independently of raw ability.', $lyceon_json$[{"key":"A","text":"Training under distinguished mentors provides young scientists with advantages that cannot be fully explained by the students' innate talent alone."},{"key":"B","text":"Nobel laureates owe their achievements primarily to the social connections provided by their mentors rather than to scientific skill."},{"key":"C","text":"Harriet Zuckerman's research conclusively disproved the idea that talent plays any role in scientific success."},{"key":"D","text":"The practice of scientific apprenticeship has declined significantly since the 1970s, reducing opportunities for young researchers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Zuckerman''s finding that training under eminent mentors provided advantages beyond raw talent, and her follow-up work reinforced this by showing comparably talented researchers under non-eminent mentors achieved less. The choice about mentorship advantages independent of innate talent captures this central idea. The claim that laureates owe achievements primarily to social connections overstates the passage, which discusses tacit knowledge transfer broadly rather than reducing mentorship to mere networking. The assertion that Zuckerman disproved any role for talent misreads the passage, which acknowledges talent selection and discusses an effect that operates independently of ability, not one that eliminates ability''s role. The suggestion about apprenticeship declining since the 1970s introduces an idea entirely absent from the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22PBJUZ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on sustainable architecture and wants to emphasize the environmental benefits of green roofs over traditional roofing. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23GCUOL', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The literary critic observed that while Haruki Murakami''s early novels often presented surreal events with a detached, almost clinical tone, his later works ______ the bizarre with palpable emotional urgency, creating a dissonance that many readers found simultaneously unsettling and deeply moving.', $lyceon_json$[{"key":"A","text":"suffused"},{"key":"B","text":"catalogued"},{"key":"C","text":"tempered"},{"key":"D","text":"obscured"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts the early detached tone with the later works'' treatment of bizarre events with emotional urgency, producing a dissonance that is both unsettling and moving. The word meaning to spread throughout or permeate precisely captures how the later works infuse the bizarre with emotional intensity. The word meaning to systematically list or classify suggests a detached cataloging approach, which describes the earlier clinical tone rather than the emotionally urgent later works. The word meaning to moderate or restrain suggests softening the bizarre elements, but the passage indicates the bizarre is maintained alongside emotional urgency to create dissonance, not moderated. The word meaning to conceal or make unclear suggests hiding the bizarre, but the passage describes the bizarre as still present and combined with emotional urgency.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24H2KWJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Fen Xiulan analyzed pottery fragments recovered from seventeen sites along the upper Mekong River dating to approximately 2,800 years ago. At each site, Xiulan measured the ratio of locally sourced clay to clay originating from deposits more than 150 kilometers away. She found that sites located near major river confluences consistently contained a higher proportion of distant clay than sites located along straight, uninterrupted stretches of the river. Xiulan argues that confluences served as natural meeting points where groups from different regions converged, facilitating the exchange of materials. If Xiulan''s interpretation is correct, one would expect that pottery fragments from confluence sites would also ________', $lyceon_json$[{"key":"A","text":"display a wider variety of decorative styles than fragments from non-confluence sites."},{"key":"B","text":"be composed exclusively of non-local clay, with no locally sourced material."},{"key":"C","text":"show evidence of more advanced kiln technology than fragments from non-confluence sites."},{"key":"D","text":"be found in smaller quantities than fragments from non-confluence sites."}]$lyceon_json$::jsonb, 'A', NULL, E'If confluences functioned as exchange hubs where diverse regional groups met, pottery at those sites would logically reflect contact with multiple traditions, producing a wider variety of decorative styles. The expectation of exclusively non-local clay overstates the finding; Xiulan found a higher proportion of distant clay, not the absence of local clay. The prediction of more advanced kiln technology assumes that inter-group contact would produce technological advancement, an inference not supported by Xiulan''s argument about material exchange. The expectation of smaller fragment quantities contradicts what one would predict at a busy meeting point, where more activity would likely produce more material remains.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24OKD44', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding would most directly undermine the conclusion drawn by Okafor and Lin?', E'Neuroscientists Okafor and Lin conducted a study examining decision-making speed in bilingual adults. They found that bilinguals who regularly switch between languages throughout the day made faster decisions on a standardized cognitive assessment than monolinguals matched for age, education, and socioeconomic status. Okafor and Lin concluded that the habitual practice of managing two active language systems enhances general cognitive processing speed, conferring a domain-general executive function advantage.', $lyceon_json$[{"key":"A","text":"Bilinguals who rarely switch between languages and instead use each language in separate, fixed contexts performed equally fast on the same cognitive assessment as the frequent switchers in Okafor and Lin's study."},{"key":"B","text":"The bilingual participants in Okafor and Lin's study reported higher levels of daily physical exercise than the monolingual participants."},{"key":"C","text":"A separate study found that trilingual adults performed no faster on cognitive assessments than bilingual adults."},{"key":"D","text":"Monolingual adults who practiced rapid task-switching exercises for six months showed no improvement in decision-making speed on the same assessment."}]$lyceon_json$::jsonb, 'A', NULL, E'Okafor and Lin concluded that habitual language switching specifically enhances cognitive processing speed. If bilinguals who rarely switch languages performed equally fast, the advantage could not be attributed to the practice of switching itself but might instead stem from bilingualism in general or some other factor, directly undermining the causal claim about switching. The finding about higher physical exercise levels among bilingual participants would suggest a potential confound in the study but does not directly address whether language switching is the operative mechanism. The finding about trilinguals performing no faster than bilinguals concerns adding a third language, which does not test the specific claim about switching frequency within two languages. The finding about monolinguals failing to improve through task-switching exercises addresses a different population and a different kind of switching, so it does not directly challenge the claim that habitual language switching in bilinguals enhances processing speed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW264CYKM', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the restoration crew arrived at the eighteenth-century textile mill in the autumn of 2021, exposure to decades of unchecked moisture and structural neglect ______ much of the building''s original timber framework beyond repair.', $lyceon_json$[{"key":"A","text":"had damaged"},{"key":"B","text":"has damaged"},{"key":"C","text":"was damaging"},{"key":"D","text":"damaged"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction ''by the time [past event]'' establishes a temporal sequence requiring the past perfect tense in the main clause to indicate that one action was completed before another past action occurred. The damage to the framework was already complete before the crew arrived, so the past perfect ''had damaged'' is the correct form. The present perfect ''has damaged'' is inappropriate because the entire context is anchored in the past (''arrived,'' ''autumn of 2021''), and the present perfect links a past event to the present moment. The past progressive ''was damaging'' implies the damage was still ongoing at the moment of arrival, but the phrase ''beyond repair'' indicates the damage had already reached completion. The simple past ''damaged'' fails to convey the completed-before-arrival sequence that ''by the time'' demands in Standard English.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26WAB10', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the Helmholtz Centre for Ocean Research have long hypothesized that deep-sea hydrothermal vents support microbial communities through chemosynthesis rather than photosynthesis. Recent expeditions to the Mid-Cayman Rise confirmed this hypothesis by identifying thriving bacterial colonies at depths exceeding 4,900 meters, where sunlight is entirely absent. ______ the team discovered that some of these colonies metabolize hydrogen sulfide at rates significantly higher than those observed at shallower vents, suggesting that extreme pressure may enhance certain chemosynthetic pathways.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"In other words,"},{"key":"C","text":"Furthermore,"},{"key":"D","text":"In comparison,"}]$lyceon_json$::jsonb, 'C', NULL, E'The final sentence introduces an additional finding from the same expedition that extends the preceding discovery. The transition "Furthermore" correctly signals that supplementary information is being added. The option "Nevertheless" implies a concession or contrast, but the final sentence does not contradict or qualify the preceding one. The option "In other words" signals a restatement, yet the final sentence presents a new finding rather than rephrasing the previous one. The option "In comparison" suggests a direct comparison between two equivalent items, but the passage is building on a single line of evidence, not contrasting two parallel findings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27V06XS', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Urban ecologist Maren Hofstad studied pigeon populations across eleven European cities and found that pigeons in cities with extensive pedestrian plazas foraged more boldly in close proximity to humans than pigeons in cities dominated by vehicle traffic. Hofstad attributes this behavioral difference to habituation: pigeons in pedestrian-heavy areas encounter slow-moving, generally non-threatening humans far more frequently than pigeons in traffic-dominated cities, where human foot traffic is sparser and more unpredictable. Based on these findings, Hofstad would most likely predict that if a traffic-dominated city were to convert a major roadway into a pedestrian plaza, the local pigeon population would ________', $lyceon_json$[{"key":"A","text":"gradually begin foraging closer to humans as the birds habituate to increased pedestrian presence."},{"key":"B","text":"immediately relocate to a different traffic-dominated area of the city."},{"key":"C","text":"show no change in foraging behavior regardless of the altered environment."},{"key":"D","text":"begin avoiding the newly pedestrianized area due to the unfamiliar conditions."}]$lyceon_json$::jsonb, 'A', NULL, E'Hofstad''s research links pedestrian-heavy environments to bolder pigeon foraging through habituation. The logical extension is that converting a road to a pedestrian plaza would gradually increase human foot traffic, leading pigeons to habituate and forage more boldly over time. The prediction that pigeons would immediately relocate overstates the behavioral response and contradicts the habituation framework, which implies gradual adjustment rather than flight. The prediction of no behavioral change contradicts Hofstad''s central finding that the pedestrian environment correlates with behavioral differences. The prediction that pigeons would avoid the area introduces avoidance behavior unsupported by the passage, which describes habituation leading to bolder behavior, not aversion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A3KFEN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The conservation program, which was established in 2011 and which, after securing emergency funding from three separate international wildlife ______ expanded its scope to include fourteen additional species of critically endangered amphibians, has been credited with preventing at least two documented extinctions in Central America.', $lyceon_json$[{"key":"A","text":"foundations, expanded"},{"key":"B","text":"foundations expanded"},{"key":"C","text":"foundations; expanded"},{"key":"D","text":"foundations. Expanded"}]$lyceon_json$::jsonb, 'A', NULL, E'This sentence has a deeply nested structure: the main clause (''The conservation program... has been credited...'') contains a nonrestrictive relative clause (''which was established in 2011 and which... expanded its scope...''), and within that relative clause, a parenthetical adverbial phrase (''after securing emergency funding from three separate international wildlife foundations'') is set off by commas. Because this parenthetical opens with a comma after the second ''which,'' it must close with a comma after ''foundations'' so that the relative clause can continue with ''expanded.'' Omitting the closing comma leaves the parenthetical unresolved, creating a confusing run-on within the relative clause that obscures the sentence''s grammatical relationships. A semicolon would fragment the interior of the relative clause at an inappropriate point. A period after ''foundations'' would sever the relative clause from the main clause entirely, producing a fragment beginning with ''Expanded'' that has no grammatical connection to the subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AOHNQ9', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Groningen recently demonstrated that certain species of arctic lichen can survive prolonged exposure to simulated Martian conditions. The lichens were placed in a chamber replicating the thin carbon dioxide atmosphere, intense ultraviolet radiation, and extreme temperature swings characteristic of the Martian surface. After 34 days, the organisms not only remained alive but continued to photosynthesize at measurable rates. The findings have reinvigorated discussions about the plausibility of detecting microbial life on Mars, since they suggest that at least some Earth organisms possess the metabolic flexibility to endure conditions once thought to be universally lethal.', $lyceon_json$[{"key":"A","text":"Arctic lichens are the most resilient organisms found on Earth."},{"key":"B","text":"Certain arctic lichens can survive conditions that closely mimic those on Mars."},{"key":"C","text":"Scientists now believe that microbial life currently exists on the Martian surface."},{"key":"D","text":"Ultraviolet radiation on Mars is less damaging to organisms than previously assumed."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centrally describes how arctic lichens survived simulated Martian conditions and continued to photosynthesize, making the choice about lichens surviving Mars-like conditions the best statement of the main idea. The claim that arctic lichens are the most resilient organisms on Earth goes beyond what the passage states, which only says certain species survived one particular experiment. The assertion that scientists believe microbial life currently exists on Mars overstates the passage, which merely says the findings reinvigorated discussions about the plausibility of detecting such life. The suggestion that ultraviolet radiation is less damaging than assumed misreads the passage, which does not diminish Mars''s UV threat but instead highlights the lichens'' metabolic flexibility.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BLHCLJ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, the Hungarian physician Ignaz Semmelweis observed that women in maternity wards staffed by medical students died of childbed fever at rates nearly five times higher than those in wards staffed by midwives. He hypothesized that the students, who routinely performed autopsies before examining patients, were transferring ''cadaverous particles'' on their hands. When Semmelweis instituted mandatory handwashing with chlorinated lime solution, the mortality rate in the student-staffed ward dropped from 18 percent to under 2 percent within months. Despite this dramatic evidence, Semmelweis''s colleagues largely rejected his findings, and widespread adoption of antiseptic practices did not occur until decades later.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes a hypothesis and its successful test, and then notes the delayed acceptance of the results."},{"key":"B","text":"It compares two competing medical theories and evaluates the evidence for each before reaching a conclusion."},{"key":"C","text":"It traces the development of antiseptic medicine from its earliest theoretical foundations to its modern applications."},{"key":"D","text":"It describes a medical crisis, explains why existing treatments failed, and proposes an alternative approach."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a clear sequence: Semmelweis observed a mortality disparity (observation), proposed that cadaverous particles caused the difference (hypothesis), implemented handwashing that reduced mortality (successful test), and then faced rejection from colleagues (delayed acceptance). This matches the option describing an observation, hypothesis with test, and delayed acceptance. The option about comparing two competing theories is inaccurate because the passage presents only Semmelweis''s hypothesis, not a rival theory. The option about tracing antiseptic medicine to modern applications overstates the passage''s scope; it ends with the rejection of Semmelweis''s findings and does not discuss modern practices. The option about describing a crisis and proposing an alternative mischaracterizes the structure; the passage does not frame existing treatments as failures or position Semmelweis''s approach as a proposal — it narrates what he actually did and the results.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C2M1QS', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'The economist Elinor Ostrom challenged the prevailing view that common-pool resources — fisheries, forests, irrigation systems — inevitably succumb to overexploitation unless privatized or managed by central governments. Through decades of fieldwork across dozens of countries, she documented communities that had sustained shared resources for centuries through locally devised rules and monitoring systems.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CS60ID', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Coral reefs occupy less than one percent of the ocean floor. Yet these structures support roughly twenty-five percent of all known marine species. [underlined: Marine biologists have documented over four thousand species of fish alone that depend on reef ecosystems for shelter, breeding grounds, or food sources.] This extraordinary concentration of life has led researchers to call reefs the ''rainforests of the sea.''', $lyceon_json$[{"key":"A","text":"It provides a specific example that supports the preceding claim about the biodiversity of coral reefs."},{"key":"B","text":"It introduces a new line of argument about why coral reefs should be preserved."},{"key":"C","text":"It challenges the assumption that coral reefs are important to marine ecosystems."},{"key":"D","text":"It presents the methodology used by marine biologists to study reef ecosystems."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence cites a concrete statistic — over four thousand fish species depending on reefs — directly after the claim that reefs support roughly twenty-five percent of all marine species. Providing a specific figure to substantiate a general claim is a classic supporting-example function. The option about introducing a preservation argument goes beyond what the text states; the passage describes biodiversity but does not argue for conservation action. The option about challenging the importance of reefs contradicts the passage, which emphasizes reefs'' extraordinary concentration of life. The option about presenting methodology mischaracterizes the sentence; it offers a finding (species count), not a description of research methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D2DVO2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The thermohaline circulation—a global system of deep-ocean currents driven by differences in water temperature and salinity rather than by surface ______ plays a crucial role in redistributing heat from equatorial regions toward the poles and thus moderating Earth''s climate over millennial timescales.', $lyceon_json$[{"key":"A","text":"winds, plays"},{"key":"B","text":"winds—plays"},{"key":"C","text":"winds; plays"},{"key":"D","text":"winds, it plays"}]$lyceon_json$::jsonb, 'B', NULL, E'The parenthetical element ''a global system of deep-ocean currents driven by differences in water temperature and salinity rather than by surface winds'' is opened with a dash after ''circulation.'' To maintain proper punctuation symmetry, the parenthetical must close with a matching dash before the verb ''plays.'' Using a comma to close a dash-opened parenthetical creates a mismatched pair of delimiters, which is nonstandard. A semicolon would incorrectly split the subject ''thermohaline circulation'' from its verb ''plays,'' severing the main clause at the wrong point. The option inserting ''it'' after a comma both fails to close the dash-opened parenthetical and introduces a redundant pronoun that produces a grammatically fractured sentence, since ''the thermohaline circulation'' already serves as the subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DVNJMU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Among the hundreds of clay tablets unearthed last spring from the ruins of the ancient Mesopotamian city of Nippur ______ a remarkably well-preserved mathematical text describing a method for calculating the area of irregular quadrilaterals—a technique historians had not previously attributed to Sumerian scholars.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"was"},{"key":"C","text":"are"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'This sentence uses inverted word order: the prepositional phrase ''Among the hundreds of clay tablets...'' precedes the verb, and the true subject ''a remarkably well-preserved mathematical text'' follows it. Because ''text'' is singular, the verb must also be singular. The phrase ''last spring'' establishes a past time frame, requiring the past tense. The plural past ''were'' incorrectly agrees with the nearby plural noun ''hundreds of clay tablets,'' which belongs to the prepositional phrase and is not the subject. The plural present ''are'' fails on both number agreement and tense, since the subject is singular and the discovery occurred in the past. The plural present perfect ''have been'' is likewise wrong in both number and tense, pairing a plural auxiliary with a singular subject and using a tense that does not match the completed past action indicated by ''last spring.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JW2LSA', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Coastal Ecology Institute hypothesize that the recent decline in sea otter populations along the northern Pacific coast is primarily driven by increased predation from orcas rather than by disease or food scarcity. The biologists note that orcas in the region shifted their foraging behavior after populations of their traditional prey, Steller sea lions and harbor seals, collapsed due to overfishing of the small fish those pinnipeds depend on.', $lyceon_json$[{"key":"A","text":"Sea otter populations have declined most steeply in areas where orca activity has increased, while remaining stable in orca-free zones."},{"key":"B","text":"Sea otters in captivity have shown vulnerability to a newly identified respiratory pathogen."},{"key":"C","text":"Kelp forests, which provide food for sea otters, have expanded in several northern Pacific coastal regions."},{"key":"D","text":"Orca populations throughout the Pacific have remained approximately constant over the past two decades."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that orca predation drives sea otter decline. A finding showing that otter decline correlates geographically with increased orca activity—and that otters remain stable where orcas are absent—would most directly support predation as the cause. A finding about captive sea otters'' susceptibility to a respiratory pathogen would support the alternative disease explanation, not the orca-predation hypothesis. A finding that kelp forests have expanded would undermine food scarcity as a cause but would not positively support orca predation. A finding that orca populations have remained constant does not directly support increased predation; predation pressure can change through behavioral shifts even without population growth.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MCTKF9', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Thriving in the damp understory of temperate rainforests and forming intricate symbiotic networks with the roots of surrounding conifers ______ play a vital role in nutrient cycling by transferring phosphorus and nitrogen between trees through underground fungal pathways.', $lyceon_json$[{"key":"A","text":", chanterelle mushrooms"},{"key":"B","text":". Chanterelle mushrooms"},{"key":"C","text":"; chanterelle mushrooms"},{"key":"D","text":": chanterelle mushrooms"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with a participial phrase (''Thriving in the damp understory... surrounding conifers'') that modifies the subject ''chanterelle mushrooms.'' A comma is the only appropriate punctuation to separate an introductory participial phrase from the main clause it modifies. Placing a period after ''conifers'' would turn the participial phrase into a sentence fragment, since it contains no independent subject or finite verb. A semicolon requires two independent clauses on either side, but the participial phrase is not an independent clause. A colon similarly demands a complete independent clause before it, which the participial phrase does not provide.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MX6C47', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Priya Chandrasekar has shown that microlending programs in rural Karnataka substantially increased household income among participants during the first three years. ______ Chandrasekar''s longitudinal data reveal that these gains plateaued after the fifth year, as borrowers who expanded their enterprises faced market saturation in the limited local economy, effectively capping the growth that microloans alone could sustain.', $lyceon_json$[{"key":"A","text":"That is,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"Even so,"},{"key":"D","text":"To that end,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence establishes that microlending produced substantial income gains, while the second sentence concedes that those gains eventually plateaued. The transition "Even so" correctly signals that the second sentence acknowledges a complication or limitation despite the positive result just described. The option "That is" implies the second sentence is restating or clarifying the first, but the plateau finding introduces new and contrasting information rather than rephrasing the initial claim. The option "Similarly" suggests the second sentence presents a parallel case, yet the plateau is a divergence from the initial upward trend, not a repetition of it. The option "To that end" implies the second sentence describes an action taken to achieve the goal mentioned in the first, but the second sentence reports an outcome, not a purposeful action.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OT5YT5', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PJO4CX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article about the glass harmonica for a music history class. The student wants to introduce the instrument to readers who may be unfamiliar with it. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PSN6QY', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city council has mandated that every new commercial building constructed within the historic district ______ the same limestone cladding and cornice dimensions as the surrounding nineteenth-century structures, a requirement that architects say significantly increases construction costs.', $lyceon_json$[{"key":"A","text":"features"},{"key":"B","text":"feature"},{"key":"C","text":"will feature"},{"key":"D","text":"would feature"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb ''mandated'' triggers the mandative subjunctive in the ''that'' clause that follows it. In Standard English, verbs of demand, requirement, and recommendation—such as ''mandate,'' ''require,'' ''insist,'' and ''recommend''—take the subjunctive mood, which uses the bare infinitive (base form) of the verb regardless of the subject''s number. Although ''every new commercial building'' is grammatically singular and would ordinarily take the indicative ''features,'' the subjunctive requires the uninflected base form ''feature.'' The option using ''will feature'' incorrectly inserts a future-tense auxiliary into the subjunctive construction, which is not permitted in Standard English after verbs of demand. The option using ''would feature'' introduces conditionality, suggesting the requirement is hypothetical rather than enacted, which contradicts the definitive meaning of ''has mandated.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RJ571B', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Economist Raj Patel has challenged the widespread assumption that subsistence farmers in developing nations would benefit most from adopting high-yield crop varieties developed through modern agricultural research. Patel acknowledges that such varieties can dramatically increase per-hectare output under optimal conditions, but he argues that the conditions required—consistent irrigation, synthetic fertilizers, and pest-management chemicals—are precisely those that subsistence farmers cannot reliably access. When farmers adopt high-yield varieties without the full input package, yields often fall below those of traditional cultivars adapted to local soil and rainfall patterns. Moreover, Patel contends, the debt incurred from purchasing seeds and partial inputs can destabilize households that previously maintained modest but sustainable food production. Thus, Patel concludes, what appears to be a technological solution may function as an economic trap for the very populations it ostensibly serves.', $lyceon_json$[{"key":"A","text":"High-yield crop varieties require conditions that subsistence farmers typically lack, potentially making adoption harmful rather than beneficial."},{"key":"B","text":"Modern agricultural research has failed to develop crop varieties suitable for use in developing nations."},{"key":"C","text":"Subsistence farmers should return to exclusively traditional farming methods to ensure household economic stability."},{"key":"D","text":"The primary obstacle to agricultural improvement in developing nations is the high cost of synthetic fertilizers."}]$lyceon_json$::jsonb, 'A', NULL, E'Patel''s central claim, as developed across the passage, is that high-yield varieties demand inputs subsistence farmers cannot reliably access, which can cause yields to drop below traditional cultivar levels and can create destabilizing debt—making adoption potentially harmful. The choice capturing the mismatch between required conditions and farmer circumstances, and the resulting potential for harm, states this claim accurately. The assertion that modern agricultural research has failed to develop suitable varieties overstates Patel''s position; he acknowledges that high-yield varieties work under optimal conditions, so the problem is context-dependent, not a blanket failure of the technology. The recommendation that farmers should return exclusively to traditional methods goes beyond Patel''s argument, which identifies risks of adoption without full inputs but does not prescribe abandoning modern varieties entirely. The claim that synthetic fertilizer cost is the primary obstacle reduces Patel''s multi-factor argument—covering irrigation, chemicals, and debt—to a single element.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SVH71R', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeological surveys of the Indus Valley site at Rakhigarhi have uncovered standardized weights and measures across multiple excavation layers, indicating that a centralized system of trade regulation persisted for centuries. ______ some scholars argue that the uniformity of these artifacts does not necessarily imply a single governing authority, since independent merchant guilds in later South Asian history achieved comparable standardization through voluntary cooperation rather than top-down mandate.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"However,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"In particular,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence presents a scholarly counterargument to the interpretation offered in the first sentence: while the first sentence frames standardized weights as evidence of centralized regulation, the second sentence challenges that inference by citing an alternative explanation. The transition "However" correctly marks this contrast. The option "In addition" signals supplementary information, but the second sentence contradicts rather than extends the first. The option "Consequently" implies the second sentence follows as a result of the first, yet the scholars are questioning the first sentence''s conclusion, not building on it. The option "In particular" signals a specific example illustrating the preceding point, but the second sentence challenges that point rather than exemplifying it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UYVD04', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every autumn, the concentration of dissolved minerals in the three high-altitude lakes near the summit of Mount Karisimbi ______ sharply as glacial meltwater dilutes the volcanic sediment that accumulates during the dry season.', $lyceon_json$[{"key":"A","text":"decreases"},{"key":"B","text":"decrease"},{"key":"C","text":"have decreased"},{"key":"D","text":"are decreasing"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the verb is the singular noun ''concentration,'' not the plural nouns ''minerals'' or ''lakes'' that appear in the intervening prepositional phrases. Because the subject is singular, the verb must also be singular. Additionally, the phrase ''every autumn'' signals a habitual, recurring event, which requires the simple present tense. The option using the base form ''decrease'' lacks the third-person singular inflection needed to agree with ''concentration.'' The option using ''have decreased'' pairs a plural auxiliary with a singular subject and uses the present perfect, which is inappropriate for describing a regularly recurring seasonal pattern. The option using ''are decreasing'' similarly employs a plural auxiliary and the progressive aspect, which describes an action in progress rather than a habitual occurrence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
