INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z8EWH6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'During the 1923 parliamentary debate, the opposition leader argued that the proposed tariff would ______ domestic manufacturers by shielding them from the competitive pressures that drive innovation and efficiency improvements.', $lyceon_json$[{"key":"A","text":"debilitate"},{"key":"B","text":"galvanize"},{"key":"C","text":"supplant"},{"key":"D","text":"exonerate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states the tariff would shield manufacturers from competitive pressures that drive innovation and efficiency, meaning the protection would ultimately weaken them. The word meaning to make weak or feeble captures this harmful consequence of removing competitive incentives. The word meaning to shock or excite into action suggests energizing, which contradicts the argument that shielding from competition is damaging. The word meaning to take the place of describes replacement, but the passage discusses weakening manufacturers, not replacing them. The word meaning to clear from accusation relates to legal or moral blame, which is entirely unrelated to the economic argument being made.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${